import {Button, Tooltip} from '@primer/react'
import pluralize from 'pluralize'
import {useEffect, useState} from 'react'
import {SharedDismissalDialog} from './components/SharedDismissalDialog'

export interface SharedDismissalButtonProps {
  alertNumbers: number[]
  alertNumbersElementId?: string
  path: string
  delegatedAlertDismissalEnabled: boolean
  codeSecurity: boolean
  disabled: boolean
  prReviewThreadId?: number
  buttonSize?: 'small' | 'medium' | 'large'
}
export function SharedDismissalButton(props: SharedDismissalButtonProps) {
  const {
    alertNumbers: initialAlertNumbers,
    alertNumbersElementId,
    path,
    delegatedAlertDismissalEnabled,
    codeSecurity,
    disabled,
    prReviewThreadId,
    buttonSize = 'medium',
  } = props
  const [isOpen, setOpen] = useState(false)
  const [alertNumbers, setAlertNumbers] = useState<number[]>(initialAlertNumbers)

  const entity = codeSecurity ? pluralize('alert', alertNumbers.length) : pluralize('finding', alertNumbers.length)
  const buttonLabel = `Dismiss ${entity}`
  const tooltipText = 'Request pending'

  useEffect(() => {
    if (!alertNumbersElementId) {
      return
    }

    const alertNumbersElement = document.getElementById(alertNumbersElementId)
    if (!alertNumbersElement) {
      return
    }

    const listener = () => {
      setAlertNumbers(JSON.parse(alertNumbersElement.textContent))
    }

    alertNumbersElement.addEventListener('change', listener)
    return () => {
      alertNumbersElement.removeEventListener('change', listener)
    }
  }, [alertNumbersElementId])

  const dismissButton = (
    <Button inactive={disabled} size={buttonSize} onClick={!disabled ? () => setOpen(true) : undefined}>
      {buttonLabel}
    </Button>
  )

  return (
    <>
      {disabled ? <Tooltip text={tooltipText}>{dismissButton}</Tooltip> : dismissButton}
      {isOpen && (
        <SharedDismissalDialog
          setOpen={setOpen}
          alertNumbers={alertNumbers}
          path={path}
          delegatedAlertDismissalEnabled={delegatedAlertDismissalEnabled}
          codeSecurity={codeSecurity}
          prReviewThreadId={prReviewThreadId}
        />
      )}
    </>
  )
}

try{ SharedDismissalButton.displayName ||= 'SharedDismissalButton' } catch {}