import {useMutation, type UseMutationResult} from '@github-ui/react-query'
import {fetchJson} from '../utils/fetch-json'

export type SharedDismissalRequest = {
  alertNumbers: number[]
  resolution: string
  dismissalComment: string
  prReviewThreadId?: number
  campaignNumber?: number
}

export type SharedDismissalResponse = {
  message: string
}

export function useSharedDismissalMutation(
  path: string,
): UseMutationResult<SharedDismissalResponse, Error, SharedDismissalRequest> {
  return useMutation({
    mutationFn: request => {
      const body: Record<string, unknown> = {
        alert_numbers: request.alertNumbers,
        resolution: request.resolution,
        resolution_note: request.dismissalComment,
        pr_review_thread_id: request.prReviewThreadId,
        campaign_number: request.campaignNumber,
      }

      return fetchJson(path, {
        method: 'put',
        body,
      })
    },
  })
}
